২৪. Python + FastAPI দিয়ে AI Service AI ইকোসিস্টেমের বেশিরভাগ SDK আগে Python-এ আসে, আর FastAPI AI-র জন্য জনপ্রিয় backend পছন্দ — async, streaming ও Pydantic validation, তিনটাই LLM অ্যাপের কাজে লাগে। (ধারণাগুলোর বিস্তারিত ব্যাখ্যা AI Engineering কোর্সে ।) LLM API কল — SDK দিয়ে pip install anthropic openai # যেটা লাগে export ANTHROPIC_API_KEY=... # key কোডে লিখবেন না (Windows: setx / .env) import anthropic client = anthropic.Anthropic() # ANTHROPIC_API_KEY environment থেকে নেয় msg = client.messages.create( model="claude-sonnet-5-5", # আপনার অ্যাকাউন্টে উপলব্ধ model-এর নাম দিন max_tokens=500, system="তুমি একজন সংক্ষিপ্ত উত্তরদাতা। বাংলায় উত্তর দাও।", messages=[{"role": "user", "content": "Dependency Injection কী?"}], ) print(msg.content[0].text) print(msg.usage.input_tokens, msg.usage.output_tokens) # cost হিসাবের জন্য # OpenAI SDK-র একই ধারণা: # from openai import OpenAI # r = OpenAI().chat.completions.create(model="...", messages=[...]) # print(r.choices[0].message.content) SDK-র API বদলায় Model নাম, parameter ও response কাঠামো সময়ের সাথে বদলায় — ব্যবহারের আগে প্রদানকারীর বর্তমান ডকুমেন্টেশন মিলিয়ে নিন। ধারণা (messages, system, max_tokens, usage) সবার একই। FastAPI endpoint দিয়ে LLM wrap করা from fastapi import FastAPI, HTTPException from pydantic import BaseModel, Field import anthropic app = FastAPI() client = anthropic.AsyncAnthropic() # async client — event loop আটকায় না class AskIn(BaseModel): question: str = Field(min_length=3, max_length=2000) # ইনপুট সীমা (cost ও abuse রোধ) class AskOut(BaseModel): answer: str input_tokens: int output_tokens: int @app.post("/ask", response_model=AskOut) async def ask(body: AskIn): try: msg = await client.messages.create( model="claude-sonnet-5-5", max_tokens=600, messages=[{"role": "user", "content": body.question}], ) except anthropic.RateLimitError: raise HTTPException(429, "একটু পরে চেষ্টা করুন") except anthropic.APIError: raise HTTPException(502, "AI সেবা সাময়িকভাবে অনুপলব্ধ") return AskOut(answer=msg.content[0].text, input_tokens=msg.usage.input_tokens, output_tokens=msg.usage.output_tokens) Best practice API key কখনো frontend-এ নয় — সবসময় আপনার FastAPI backend-ই provider-কে কল করবে। ইনপুটের দৈর্ঘ্য সীমিত করুন, per-user rate limit রাখুন, প্রতি call-এর token/cost লগ করুন (AI কোর্সের Production অধ্যায় দেখুন)। Streaming — token আসার সাথে সাথে client-কে পাঠানো (SSE) from fastapi.responses import StreamingResponse @app.get("/chat/stream") async def chat_stream(q: str): async def gen(): async with client.messages.stream( model="claude-sonnet-5-5", max_tokens=600, messages=[{"role": "user", "content": q}], ) as stream: async for text in stream.text_stream: yield f"data: {text}

" # SSE ফরম্যাট yield "data: [DONE]

" return StreamingResponse(gen(), media_type="text/event-stream") Structured Output — JSON + Pydantic validation from pydantic import BaseModel, ValidationError class Invoice(BaseModel): vendor: str total: float currency: str PROMPT = """নিচের টেক্সট থেকে শুধু JSON দাও (কোনো ব্যাখ্যা নয়): {"vendor": str, "total": number, "currency": str} টেক্সট: ABC Traders এর বিল, মোট 12500 টাকা (BDT)।""" async def extract(text_prompt: str, retries: int = 2) -> Invoice: for _ in range(retries + 1): msg = await client.messages.create( model="claude-sonnet-5-5", max_tokens=300, messages=[{"role": "user", "content": text_prompt}], ) raw = msg.content[0].text try: return Invoice.model_validate_json(raw) # validate না হলে আবার চেষ্টা except ValidationError: continue raise HTTPException(502, "AI সঠিক ফরম্যাটে উত্তর দেয়নি") কেন validate জরুরি মডেলের output একটা prediction — JSON চাইলেও ভুল/অতিরিক্ত টেক্সট আসতে পারে। Pydantic দিয়ে validate করে তবেই ব্যবহার করুন; provider-এর structured output/tool-calling ফিচার থাকলে সেটাও কাজে লাগান। Embedding ও সরল Semantic Search (NumPy) import numpy as np def cosine(a, b): a, b = np.array(a), np.array(b) return float(a @ b / (np.linalg.norm(a) * np.linalg.norm(b))) # docs = [(text, embedding_vector), ...] — embedding আসে provider-এর embedding API থেকে def search(query_vec, docs, k=3): scored = [(cosine(query_vec, vec), text) for text, vec in docs] return sorted(scored, reverse=True)[:k] # বড় ডেটায়: PostgreSQL + pgvector (Python-এ `pgvector` package SQLAlchemy-র সাথে চলে) Tool Calling লুপের কাঠামো # ধারণা (provider-নির্বিশেষ): tools = {"get_balance": lambda account_id: {"balance": 15000}} # আপনার আসল function def run_agent(user_msg): messages = [{"role": "user", "content": user_msg}] for _ in range(5): # সর্বোচ্চ iteration — অসীম লুপ রোধ reply = call_llm(messages, tools=tool_schemas) # মডেল কোন tool চায় তা জানায় if not reply.tool_calls: return reply.text # চূড়ান্ত উত্তর for call in reply.tool_calls: result = tools[call.name](**call.args) # আসল execution আপনার কোডে messages.append(tool_result_message(call, result)) raise RuntimeError("iteration সীমা অতিক্রম") পূর্ণ বিবরণ, নিরাপত্তা (prompt injection, least privilege) ও RAG-এর জন্য AI Engineering কোর্সের Tool Calling, Agents ও Safety অধ্যায় দেখুন। Retry ও Timeout # pip install tenacity from tenacity import retry, stop_after_attempt, wait_exponential @retry(stop=stop_after_attempt(3), wait=wait_exponential(multiplier=1, min=1, max=10)) async def call_with_retry(**kwargs): return await client.messages.create(**kwargs)
